const msg = $json.message || ($json.body && $json.body.message) || {};
const text = (msg.text || '').trim();
const chatId = msg.chat ? msg.chat.id : null;
const voice = msg.voice || msg.audio || null;
const voiceFileId = voice ? voice.file_id : null;

let branch = 'other';
let hotelQuery = '';
let createNew = false;

const helpMatch = text.match(/^\/help$/i);
const hotelsListMatch = text.match(/^\/hotels$/i);
const uploadMatch = text.match(/^\/upload\s+(.+)/i);
const islandUploadMatch = text.match(/^\/island\s+(.+)/i);
const islandReadyMatch = text.match(/^острів\s+готово[,:]?\s*(.+)/i);
const readyMatch = text.match(/^готово[,:]?\s*(.+)/i);
const voiceStartMatch = text.match(/^\/voice$/i);
const voiceCancelMatch = text.match(/^\/cancel$/i);
const newHotelMatch = text.match(/^\/newhotel\s+(.+)/i);

if (helpMatch) {
  branch = 'help';
} else if (hotelsListMatch) {
  branch = 'list_hotels';
} else if (voiceStartMatch) {
  branch = 'voice_start';
} else if (voiceCancelMatch) {
  branch = 'voice_cancel';
} else if (newHotelMatch) {
  branch = 'upload';
  hotelQuery = newHotelMatch[1].trim();
  createNew = true;
} else if (uploadMatch) {
  branch = 'upload';
  hotelQuery = uploadMatch[1].trim();
} else if (islandUploadMatch) {
  branch = 'island_upload';
  hotelQuery = islandUploadMatch[1].trim();
} else if (islandReadyMatch) {
  branch = 'island_ready';
  hotelQuery = islandReadyMatch[1].trim();
} else if (readyMatch) {
  branch = 'ready';
  hotelQuery = readyMatch[1].trim();
}

return [{ json: { branch, hotel_query: hotelQuery, chat_id: chatId, raw_text: text, voice_file_id: voiceFileId, create_new: createNew } }];

const routeData = $('Code - Route Message').item.json;
const rows = $input.all().map(i => i.json).filter(r => r && r.hotel_id);
const norm = s => String(s || '').toLowerCase().replace(/[^\p{L}\p{N}]+/gu, '');
const q = norm(routeData.hotel_query);
let match = rows.find(r => norm(r.name) === q) || null;
if (!match && !routeData.create_new && q.length >= 5) {
  const cand = rows.filter(r => { const n = norm(r.name); return n.includes(q) || q.includes(n); });
  if (cand.length === 1) match = cand[0];
}
const exists = !!match;
const stop = new Set(['resort', 'resorts', 'hotel', 'hotels']);
const tokens = String(routeData.hotel_query || '').toLowerCase().split(/[^\p{L}\p{N}]+/u).filter(t => t.length >= 4 && !stop.has(t));
const similar = exists ? [] : rows.filter(r => { const n = norm(r.name); return tokens.some(t => n.includes(t)); }).slice(0, 5).map(r => r.name);
return [{ json: {
  hotel_exists: exists,
  hotel_id: exists ? match.hotel_id : null,
  hotel_name: exists ? match.name : routeData.hotel_query,
  chat_id: routeData.chat_id,
  hotel_query: routeData.hotel_query,
  create_new: routeData.create_new === true,
  similar,
} }];

const checkData = $('Code - Check Hotel Found (Upload)').item.json;
const lastRows = $input.all();
let lastNum = 0;
if (lastRows.length && lastRows[0].json && lastRows[0].json.hotel_id) {
  const m = String(lastRows[0].json.hotel_id).match(/(\d+)$/);
  if (m) lastNum = parseInt(m[1], 10);
}
const nextId = 'HTL-' + String(lastNum + 1).padStart(3, '0');
return [{ json: {
  hotel_id: nextId,
  name: checkData.hotel_query,
  country: 'Уточнити',
  status: 'needs_review',
  content_status: 'Not Ready',
  chat_id: checkData.chat_id
} }];

const r = $input.first().json;
const ctx = $('Code - Generate Stub Hotel').item.json;
return [{ json: { hotel_id: r.hotel_id || ctx.hotel_id, hotel_name: r.name || ctx.name, chat_id: ctx.chat_id, is_new_hotel: true } }];

const c = $json;
const slug = (c.hotel_name || '').trim().replace(/[^\p{L}\p{N}]+/gu, '_').replace(/^_+|_+$/g, '');
const folderName = `${c.hotel_id}_${slug}`;
return [{ json: { ...c, folder_name: folderName } }];

const rows = $input.all();
const found = rows.find(r => r.json && r.json.id);
const ctx = $('Code - Build Folder Name').item.json;
return [{ json: { ...ctx, folder_exists: !!found, folder_id: found ? found.json.id : null, folder_link: found ? (found.json.webViewLink || ('https://drive.google.com/drive/folders/' + found.json.id)) : null } }];

const ctx = $('Code - Check Folder Found').item.json;
const f = $input.first().json;
return [{ json: { ...ctx, folder_id: f.id, folder_link: f.webViewLink || ('https://drive.google.com/drive/folders/' + f.id) } }];

const c = $json;
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const newNote = c.is_new_hotel ? `

(Готель ще не було в базі — створив чернетку ${c.hotel_id}, потрібно буде дослідити пізніше.)` : '';
const text = `Готово, вантаж сюди 👇
${c.folder_link}${newNote}

Коли завантажиш усі фото — напиши мені:
<code>готово, ${escapeHtml(c.hotel_name)}</code>`;
return [{ json: { chat_id: c.chat_id, reply_text: text } }];

const c = $json;
let text;
const instructions = `Для ГОТЕЛЮ:
• /hotels — список готелів у базі (тапни на назву щоб скопіювати)
• /newhotel [назва] — додати НОВИЙ готель (/upload нових готелів не створює)
1) /upload [назва готелю] — дам лінк на Drive-папку
2) Залий фото на Drive
3) "готово, [назва готелю]" — заберу й опишу фото

Для ОСТРОВА (без прив'язки до готелю):
1) /island [назва острова] — дам лінк на Drive-папку
2) Залий фото на Drive
3) "острів готово, [назва острова]" — заберу й опишу фото

Для ІНФО ПРО ГОТЕЛЬ:
• /voice — розкажи про готель голосовими або текстом, я запишу
• /cancel — скасувати розмову про готель

Старі фото не чіпаю — описую тільки нові.

Напиши /help будь-коли, щоб побачити цю інструкцію знову.`;
if (c.branch === 'ready') {
  text = `Бачу, що готово по "${c.hotel_query}" 👍 Обробку фото (Vision-аналіз + запис у базу) ще добудовую — це наступний крок. Скоро зможу забирати фото автоматично.`;
} else if (c.branch === 'help') {
  text = `📸 Медіа-бібліотека TravelLab

${instructions}`;
} else {
  text = `🤖 Не розпізнав команду.

${instructions}`;
}
return [{ json: { chat_id: c.chat_id, reply_text: text } }];

