const rows = $input.all().map(r => r.json).filter(r => r && r.hotel_id);
const chatId = $('Code - Route Message').item.json.chat_id;
const escapeHtml = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
if (!rows.length) {
  return [{ json: { chat_id: chatId, reply_text: 'У базі поки нема жодного готелю. Напиши /upload [назва готелю], щоб додати перший.' } }];
}
rows.sort((a, b) => (a.name || '').localeCompare(b.name || '', 'uk'));
const lines = rows.map((r, i) => {
  const icon = r.status === 'needs_review' ? '🆕' : '✅';
  return `${i + 1}. ${icon} <code>${escapeHtml(r.name)}</code>`;
});
const text = `📋 Готелі в базі (${rows.length}):\n\n${lines.join('\n')}\n\nТапни на назву щоб скопіювати, потім напиши /upload [назва] або "готово, [назва]".`;
return [{ json: { chat_id: chatId, reply_text: text } }];

